package com.specarmed;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(SpecArmedConfig.GROUP)
public interface SpecArmedConfig extends Config
{
	String GROUP = "specarmed";

	enum OrbStyle
	{
		RING,
		FILL,
		BOTH
	}

	@Getter
	@RequiredArgsConstructor
	enum OrbArea
	{
		WHOLE("Orb and number"),
		ORB_ONLY("Orb only");

		private final String name;

		@Override
		public String toString()
		{
			return name;
		}
	}

	@Getter
	@RequiredArgsConstructor
	enum SoundChoice
	{
		SHOTGUN("Shotgun", "shotgun.wav"),
		HAMMER_COCK("Hammer cock", "hammer_cock.wav");

		private final String name;
		private final String resource;

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigSection(
		name = "Orb & spec bar",
		description = "Highlight the spec orb and combat tab spec bar while spec is on",
		position = 0
	)
	String orbSection = "orb";

	@ConfigSection(
		name = "Player text",
		description = "Text above your character while spec is on",
		position = 1
	)
	String textSection = "text";

	@ConfigSection(
		name = "Sound",
		description = "Sound played when spec is turned on",
		position = 2
	)
	String soundSection = "sound";

	@ConfigItem(
		keyName = "highlightOrb",
		name = "Highlight orb",
		description = "Highlight the special attack orb while spec is on",
		section = orbSection,
		position = 0
	)
	default boolean highlightOrb()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightSpecBar",
		name = "Highlight spec bar",
		description = "Highlight the spec bar in the combat tab while spec is on",
		section = orbSection,
		position = 1
	)
	default boolean highlightSpecBar()
	{
		return true;
	}

	@ConfigItem(
		keyName = "orbArea",
		name = "Highlight area",
		description = "Highlight the whole orb including the number, or only the round orb",
		section = orbSection,
		position = 2
	)
	default OrbArea orbArea()
	{
		return OrbArea.WHOLE;
	}

	@ConfigItem(
		keyName = "orbStyle",
		name = "Style",
		description = "Ring around the orb, a fill over it, or both",
		section = orbSection,
		position = 3
	)
	default OrbStyle orbStyle()
	{
		return OrbStyle.BOTH;
	}

	@Alpha
	@ConfigItem(
		keyName = "ringColor",
		name = "Ring color",
		description = "Color of the ring/border",
		section = orbSection,
		position = 4
	)
	default Color ringColor()
	{
		return new Color(255, 215, 0, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColor",
		name = "Fill color",
		description = "Color of the fill (keep it see-through)",
		section = orbSection,
		position = 5
	)
	default Color fillColor()
	{
		return new Color(255, 215, 0, 90);
	}

	@Range(min = 1, max = 8)
	@ConfigItem(
		keyName = "ringThickness",
		name = "Ring thickness",
		description = "Thickness of the ring/border in pixels",
		section = orbSection,
		position = 6
	)
	default int ringThickness()
	{
		return 3;
	}

	@Range(min = -20, max = 20)
	@ConfigItem(
		keyName = "orbOffsetY",
		name = "Nudge up/down",
		description = "Move the orb highlight up (positive) or down (negative) in pixels",
		section = orbSection,
		position = 7
	)
	default int orbOffsetY()
	{
		return 0;
	}

	@Range(min = -20, max = 20)
	@ConfigItem(
		keyName = "orbOffsetX",
		name = "Nudge left/right",
		description = "Move the orb highlight right (positive) or left (negative) in pixels",
		section = orbSection,
		position = 8
	)
	default int orbOffsetX()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "showPlayerText",
		name = "Show text",
		description = "Show text above your character while spec is on",
		section = textSection,
		position = 0
	)
	default boolean showPlayerText()
	{
		return true;
	}

	@ConfigItem(
		keyName = "playerText",
		name = "Text",
		description = "What to show above your character",
		section = textSection,
		position = 1
	)
	default String playerText()
	{
		return "Locked n' loaded";
	}

	@ConfigItem(
		keyName = "textColor",
		name = "Text color",
		description = "Color of the text",
		section = textSection,
		position = 2
	)
	default Color textColor()
	{
		return new Color(255, 215, 0);
	}

	@Range(min = -100, max = 200)
	@ConfigItem(
		keyName = "textHeight",
		name = "Height offset",
		description = "Move the text up (higher) or down (lower)",
		section = textSection,
		position = 3
	)
	default int textHeight()
	{
		return 40;
	}

	@ConfigItem(
		keyName = "playSound",
		name = "Play sound",
		description = "Play a sound when spec is turned on",
		section = soundSection,
		position = 0
	)
	default boolean playSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sound",
		name = "Sound",
		description = "Which sound to play",
		section = soundSection,
		position = 1
	)
	default SoundChoice sound()
	{
		return SoundChoice.SHOTGUN;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "volume",
		name = "Volume",
		description = "Sound volume (0-100). Use Preview sound to hear it",
		section = soundSection,
		position = 2
	)
	default int volume()
	{
		return 70;
	}

	@ConfigItem(
		keyName = "preview",
		name = "Preview sound",
		description = "Tick to hear the current sound at the current volume",
		section = soundSection,
		position = 3
	)
	default boolean preview()
	{
		return false;
	}
}

package com.specarmed;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class SpecArmedPlayerOverlay extends Overlay
{
	private final Client client;
	private final SpecArmedPlugin plugin;
	private final SpecArmedConfig config;

	@Inject
	SpecArmedPlayerOverlay(Client client, SpecArmedPlugin plugin, SpecArmedConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isSpecOn() || !config.showPlayerText())
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		String text = config.playerText();
		if (player == null || text == null || text.isEmpty())
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeBoldFont());
		Point location = player.getCanvasTextLocation(graphics, text, player.getLogicalHeight() + config.textHeight());
		if (location != null)
		{
			OverlayUtil.renderTextLocation(graphics, location, text, config.textColor());
		}
		return null;
	}
}

package com.specarmed;

import com.google.inject.Provides;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Spec Armed",
	description = "Makes it obvious when your special attack is turned on",
	tags = {"spec", "special", "attack", "orb", "indicator", "highlight", "sound"}
)
public class SpecArmedPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private SpecArmedConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpecArmedWidgetOverlay widgetOverlay;

	@Inject
	private SpecArmedPlayerOverlay playerOverlay;

	@Getter
	private boolean specOn;

	// Varps get re-sent while logging in or hopping; don't play the sound until the first tick after that
	private boolean ready;

	@Inject
	private ConfigManager configManager;

	@Inject
	private AudioPlayer audioPlayer;

	// Opening an audio line can block for a noticeable moment, so sounds are played from
	// RuneLite's background executor instead of the client or settings-panel thread
	@Inject
	private ScheduledExecutorService executor;

	// Settings previews are delayed slightly so flipping through sounds only plays the last one
	private ScheduledFuture<?> pendingPreview;

	@Provides
	SpecArmedConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpecArmedConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(widgetOverlay);
		overlayManager.add(playerOverlay);
		clientThread.invoke(() ->
		{
			ready = client.getGameState() == GameState.LOGGED_IN;
			specOn = ready && client.getVarpValue(VarPlayerID.SA_ATTACK) == 1;
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(widgetOverlay);
		overlayManager.remove(playerOverlay);
		if (pendingPreview != null)
		{
			pendingPreview.cancel(false);
			pendingPreview = null;
		}
		specOn = false;
		ready = false;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.SA_ATTACK)
		{
			return;
		}

		boolean on = event.getValue() == 1;
		if (on && !specOn && ready && config.playSound())
		{
			executor.execute(this::playSound);
		}
		specOn = on;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			ready = false;
			specOn = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		ready = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SpecArmedConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "preview":
				if (config.preview())
				{
					schedulePreview();
					// Untick so it works like a button
					configManager.setConfiguration(SpecArmedConfig.GROUP, "preview", false);
				}
				break;
			case "sound":
				schedulePreview();
				break;
		}
	}

	private void schedulePreview()
	{
		if (pendingPreview != null)
		{
			pendingPreview.cancel(false);
		}
		pendingPreview = executor.schedule(this::playSound, 250, TimeUnit.MILLISECONDS);
	}

	private void playSound()
	{
		// AudioPlayer takes gain in decibels; 0 dB is the file's own volume
		float gain = (float) (20 * Math.log10(Math.max(config.volume(), 1) / 100f));
		try
		{
			audioPlayer.play(SpecArmedPlugin.class, config.sound().getResource(), gain);
		}
		catch (Exception e)
		{
			log.warn("Spec Armed: unable to play sound", e);
		}
	}
}

package com.specarmed;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class SpecArmedWidgetOverlay extends Overlay
{
	private final Client client;
	private final SpecArmedPlugin plugin;
	private final SpecArmedConfig config;

	@Inject
	SpecArmedWidgetOverlay(Client client, SpecArmedPlugin plugin, SpecArmedConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isSpecOn())
		{
			return null;
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		if (config.highlightOrb())
		{
			int dx = config.orbOffsetX();
			int dy = -config.orbOffsetY();
			if (config.orbArea() == SpecArmedConfig.OrbArea.WHOLE)
			{
				// The frame sprite behind both the number and the orb
				Rectangle whole = visibleBounds(InterfaceID.Orbs.SPECENERGY_BACKING);
				if (whole != null)
				{
					draw(graphics, new RoundRectangle2D.Double(whole.x + dx, whole.y + dy, whole.width, whole.height, 12, 12));
				}
			}
			else
			{
				// The round orb sprite itself (the click area sits a couple of pixels lower)
				Rectangle orb = visibleBounds(InterfaceID.Orbs.SPECENERGY_INDICATOR);
				if (orb != null)
				{
					draw(graphics, new Ellipse2D.Double(orb.x + dx, orb.y + dy, orb.width, orb.height));
				}
			}
		}

		if (config.highlightSpecBar())
		{
			Rectangle bar = visibleBounds(InterfaceID.CombatInterface.SP_ATTACKBAR);
			if (bar != null)
			{
				draw(graphics, bar);
			}
		}

		return null;
	}

	private void draw(Graphics2D graphics, Shape shape)
	{
		SpecArmedConfig.OrbStyle style = config.orbStyle();
		if (style != SpecArmedConfig.OrbStyle.RING)
		{
			graphics.setColor(config.fillColor());
			graphics.fill(shape);
		}
		if (style != SpecArmedConfig.OrbStyle.FILL)
		{
			graphics.setColor(config.ringColor());
			graphics.setStroke(new BasicStroke(config.ringThickness()));
			graphics.draw(shape);
		}
	}

	private Rectangle visibleBounds(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		// Off-screen pieces report x/y of -1
		Rectangle bounds = widget.getBounds();
		return bounds.width > 0 && bounds.height > 0 && bounds.x >= 0 && bounds.y >= 0 ? bounds : null;
	}
}

package com.specarmed;

